  const headings = Array.from(document.querySelectorAll('h2, [role="heading"]'));
  const sofitelH = headings.find(h => h.innerText.includes('Sofitel Los Angeles at Beverly Hills'));
  if (!sofitelH) return { error: "Sofitel heading not found", headings: headings.map(h => h.innerText).slice(0, 10) };

  // Find clickable parent or buttons
  let el = sofitelH;
  const chain = [];
  while (el && el !== document.body) {
    chain.push({
      tag: el.tagName,
      role: el.getAttribute('role'),
      jsaction: el.getAttribute('jsaction'),
      jscontroller: el.getAttribute('jscontroller'),
      className: el.className
    });
    el = el.parentElement;
  }
  return { chain: chain.slice(0, 8) };
});

console.log("Card inspection:", cardElements);

