const tabId = 2136412306;

// Let's test route lookup on Google Maps
// Routes to check:
// 1. Hotel 850 SVB (West Hollywood) to Griffith Observatory
// 2. Griffith Observatory to Koreatown (e.g. Park's BBQ, 955 S Vermont Ave)
// 3. Park's BBQ to Hotel 850 SVB
// 4. Hotel 850 SVB to The Getty Center
// 5. The Getty Center to Santa Monica Pier
// 6. Santa Monica Pier to Hotel 850 SVB

const routes = [
  { from: "850 N San Vicente Blvd, West Hollywood", to: "Griffith Observatory" },
  { from: "Griffith Observatory", to: "Parks BBQ, 955 S Vermont Ave, Los Angeles" },
  { from: "Parks BBQ, 955 S Vermont Ave, Los Angeles", to: "850 N San Vicente Blvd, West Hollywood" },
  { from: "850 N San Vicente Blvd, West Hollywood", to: "The Getty Center" },
  { from: "The Getty Center", to: "Santa Monica Pier" },
  { from: "Santa Monica Pier", to: "850 N San Vicente Blvd, West Hollywood" }
];

const results = [];

for (const r of routes) {
  const url = `https://www.google.com/maps/dir/${encodeURIComponent(r.from)}/${encodeURIComponent(r.to)}`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "selector_visible", value: '#section-directions-trip-0, [data-trip-index="0"], div[class*="directions"]', timeout_ms: 10000 });
  await new Promise(r => setTimeout(r, 2000));

  const tripInfo = await browserjs(tabId, () => {
    // Find travel time and distance
    const trip = document.querySelector('#section-directions-trip-0, [data-trip-index="0"]');
    if (!trip) {
      // Look for travel time text
      const matches = document.body.innerText.match(/(\d+\s*hr\s*)?(\d+\s*min)[^\n]*\n[^\n]*(\d+(\.\d+)?\s*miles)/i);
      return matches ? matches[0] : "Could not find trip container";
    }
    return trip.innerText.split('\n').filter(t => t.trim().length > 0).slice(0, 6).join(' | ');
  });
  console.log(`Route from ${r.from} to ${r.to}:`, tripInfo);
  results.push({ ...r, tripInfo });
}

